const hostToLocation = { 'tipzakske.myshopify.com': 'LOC_AALST', 'frietbooster.myshopify.com': 'LOC_BERLARE', 'de-frietchalet.myshopify.com': 'LOC_DENDER', 'friturist.myshopify.com': 'LOC_FRITURIST' };
const hook = $('Webhook (raw body)').first();
const headers = hook.json.headers ?? {};
const hmacHeader = headers['x-shopify-hmac-sha256'] ?? '';
const webhookId = headers['x-shopify-webhook-id'] ?? null;
const topic = headers['x-shopify-topic'] ?? null;
const sourceIp = headers['x-forwarded-for'] ?? null;
const hostHeader = (headers['x-shopify-shop-domain'] ?? '').toLowerCase();
const body_b64 = hook.binary?.data?.data ?? '';
const location_key = hostToLocation[hostHeader] ?? null;
if (!location_key) return [{ json: { outcome: 'unknown_host', http_status: 401, log: { event: 'unknown_host', host: hostHeader, source_ip: sourceIp, webhook_id: webhookId, topic } } }];
const rows = $items('Load Vault Secrets').map(i => i.json);
const byCur = Object.fromEntries(rows.map(r => [r.name, r.computed_hmac]));
const expCur = byCur['shopify_webhook_secret_' + location_key] ?? null;
const expPrev = byCur['shopify_webhook_secret_' + location_key + '_prev'] ?? null;
if (!expCur) return [{ json: { outcome: 'config_missing', http_status: 500, location_key, log: { event: 'webhook_secret_missing', location_key } } }];
let matched = null;
if (hmacHeader && expCur && hmacHeader === expCur) matched = 'current';
else if (hmacHeader && expPrev && hmacHeader === expPrev) matched = 'previous';
if (!matched) return [{ json: { outcome: 'hmac_fail', http_status: 401, location_key, log: { event: 'hmac_fail', location_key, source_ip: sourceIp, webhook_id: webhookId, topic } } }];
let order; try {
  const bin = atob(body_b64);
  const u8 = Uint8Array.from(bin, c => c.charCodeAt(0));
  order = JSON.parse(new TextDecoder('utf-8').decode(u8));
} catch { return [{ json: { outcome: 'invalid_payload', http_status: 200, location_key, log: { event: 'invalid_payload', location_key, webhook_id: webhookId } } }]; }
// 2026-10-16: someone bulk-fulfilled 16k+ historical orders (2022-2026) in Shopify admin;
// every one fired orders/updated + orders/fulfilled, flooding workers and raw_orders.
// Updates for orders older than 7 days carry nothing the pipeline acts on (a live order
// is created and fulfilled the same day) -> acknowledge with 200 and stop. Reuses the
// invalid_payload route (200, no insert) so no switch/connection edits are needed.
const createdMs = Date.parse(order?.created_at ?? '');
if (Number.isFinite(createdMs) && (Date.now() - createdMs) > 7 * 24 * 3600 * 1000) {
  return [{ json: { outcome: 'invalid_payload', http_status: 200, location_key, log: { event: 'ignored_stale_order', location_key, order_name: order?.name ?? null, created_at: order?.created_at, topic, webhook_id: webhookId } } }];
}
const external_ref = order?.name ? ('Shopify - ' + order.name) : null;
return [{ json: { outcome: 'accepted', http_status: 200, location_key, external_ref, raw_payload: order, headers, hmac_matched: matched, webhook_id: webhookId, log: { event: 'order_fulfilled_received', location_key, external_ref, webhook_id: webhookId, hmac_matched: matched } } }];
